    return (SZABLON_PARKOUR.replace("__TWARZ_SKOCZKA__", TWARZ_SKOCZKA_B64)
                           .replace("__TWARZ_KSIEZNICZKI__", TWARZ_KSIEZNICZKI_B64)
                           .replace("__PORADNIK_WIDEO__", PORADNIK_WIDEO_B64))


