# ======================================================================
# TRWAŁY STAN — przetrwa zamknięcie telefonu i wznowienie po jakimś czasie.
# Zapisywany w DWÓCH miejscach naraz (link + plik na serwerze).
# ======================================================================

def wczytaj_zapisany_stan():
    sciezka = sciezka_stanu()
    if os.path.exists(sciezka):
        try:
            with open(sciezka, "r", encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return None
    # Pierwsze wejście po aktualizacji: przejmujemy stary, wspólny zapis
    if os.path.exists(DOMYSLNY_PLIK_STANU):
        try:
            with open(DOMYSLNY_PLIK_STANU, "r", encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return None
    return None


def koduj_bledy_per_etap(slownik):
    return ",".join(f"{k}:{v}" for k, v in sorted(slownik.items()) if v)


def dekoduj_bledy_per_etap(tekst):
    wynik = {}
    if not tekst:
        return wynik
    for czesc in tekst.split(","):
        if ":" not in czesc:
            continue
        klucz, _, wartosc = czesc.partition(":")
        if klucz and wartosc.isdigit():
            wynik[klucz] = int(wartosc)
    return wynik


def zapisz_postep():
    st.query_params["r"] = ",".join(sorted(st.session_state.rozwiazane))
    st.query_params["n"] = ",".join(sorted(st.session_state.nieudane))
    st.query_params["b"] = koduj_bledy_per_etap(st.session_state.bledy_per_etap)
    st.query_params["j"] = st.session_state.jezyk
    if st.session_state.czas_startu:
        st.query_params["t"] = str(st.session_state.czas_startu)
    if st.session_state.get("samouczek_zrobiony"):
        st.query_params["w"] = "1"
    if st.session_state.get("staty_gier"):
        # W adresie, zeby przetrwaly ponowny skan QR i usypianie serwera
        st.query_params["s"] = json.dumps(st.session_state.staty_gier, separators=(",", ":"))
    dane = {
        "staty_gier": st.session_state.get("staty_gier", {}),
        "rozwiazane": list(st.session_state.rozwiazane),
        "nieudane": list(st.session_state.nieudane),
        "bledy_per_etap": st.session_state.bledy_per_etap,
        "jezyk": st.session_state.jezyk,
        "czas_startu": st.session_state.czas_startu,
        "samouczek_zrobiony": bool(st.session_state.get("samouczek_zrobiony")),
        "podpis_diabla": st.session_state.get("podpis_diabla"),
    }
    try:
        with open(sciezka_stanu(), "w", encoding="utf-8") as f:
            json.dump(dane, f)
    except Exception:
        pass


def zainicjuj_stan():
    if "rozwiazane" in st.session_state:
        return

    r = st.query_params.get("r", "")
    rozwiazane_url = set(x for x in r.split(",") if x)
    n = st.query_params.get("n", "")
    nieudane_url = set(x for x in n.split(",") if x)
    b = st.query_params.get("b", "")
    bledy_url = dekoduj_bledy_per_etap(b)
    j = st.query_params.get("j")
    jezyk_url = j if j in ("pl", "en") else None
    t_param = st.query_params.get("t")
    czas_url = float(t_param) if t_param else None

    zapisane = wczytaj_zapisany_stan() or {}
    rozwiazane_plik = set(zapisane.get("rozwiazane", []))
    nieudane_plik = set(zapisane.get("nieudane", []))
    bledy_plik = zapisane.get("bledy_per_etap", {})
    jezyk_plik = zapisane.get("jezyk")
    czas_plik = zapisane.get("czas_startu")

    st.session_state.rozwiazane = rozwiazane_url | rozwiazane_plik
    st.session_state.nieudane = {
        k for k in (nieudane_url | nieudane_plik)
        if next((e for e in ETAPY if e["klucz"] == k), {}).get("jedna_proba")
    }
    bledy_polaczone = dict(bledy_plik)
    for klucz_etapu, wartosc in bledy_url.items():
        bledy_polaczone[klucz_etapu] = max(bledy_polaczone.get(klucz_etapu, 0), wartosc)
    st.session_state.bledy_per_etap = bledy_polaczone
    st.session_state.jezyk = "pl"   # aplikacja tylko po polsku (bez angielskich instrukcji i podpowiedzi)
    st.session_state.czas_startu = czas_url or czas_plik
    try:
        staty_url = json.loads(st.query_params.get("s") or "{}")
    except Exception:
        staty_url = {}
    st.session_state.staty_gier = dict(zapisane.get("staty_gier", {}))
    if zapisane.get("podpis_diabla") and not st.session_state.get("podpis_diabla"):
        st.session_state.podpis_diabla = zapisane["podpis_diabla"]
    st.session_state.staty_gier.update(staty_url if isinstance(staty_url, dict) else {})

    juz_zaczela = bool(
        jezyk_url or jezyk_plik
        or st.session_state.rozwiazane or st.session_state.nieudane
        or st.session_state.bledy_per_etap
    )
    st.session_state.ekran = "menu" if juz_zaczela else "powitanie"
    st.session_state.samouczek_zrobiony = (st.query_params.get("w") == "1") or bool(zapisane.get("samouczek_zrobiony"))
    if juz_zaczela and not st.session_state.samouczek_zrobiony and not st.session_state.rozwiazane:
        st.session_state.samouczek_krok = 1     # po kłódkach, ale przed zakonczeniem samouczka

    if juz_zaczela:
        zapisz_postep()


# ======================================================================
# RENDEROWANIE POJEDYNCZYCH TYPÓW ZAGADEK
# Każdy zwraca: True (poprawnie), False (źle — dopiero co wysłane), albo
# None (nic jeszcze nie wysłano w tym przebiegu).
# ======================================================================

def renderuj_haslo(etap_dane):
    klucz = etap_dane["klucz"]

    # Treść zagadki MUSI być widoczna — bez niej nie da się jej rozwiązać.
    # (Przy wcześniejszym usuwaniu zbędnych instrukcji z etapów ta treść
    # zniknęła razem z nimi, choć tutaj jest sednem zadania.)
    if etap_dane.get("tresc"):
        st.markdown(tt(etap_dane["tresc"]))

    if etap_dane.get("format_info"):
        st.caption(tt(etap_dane["format_info"]))

    wpisane = st.text_input(t("twoja_odpowiedz"), key=f"pole_{klucz}")
    if st.button(t("sprawdz"), key=f"btn_{klucz}"):
        if znormalizuj(wpisane) == znormalizuj(etap_dane["odpowiedz"]):
            return True
        st.error(t("zle_sprobuj"))
        return False
    return None


