def renderuj_krzyzowka(etap_dane):
    klucz = etap_dane["klucz"]
    if _KOMPONENT_WYNIKU is not None and all(p.get("typ") == "ulozanka" for p in etap_dane["pytania"]):
        dane = {
            "pytania": [
                {
                    "wskazowka": tt(p["wskazowka"]),
                    "podpowiedz": tt(p["podpowiedz"]) if p.get("podpowiedz") else "",
                    "dl": len(p["odpowiedz"]),
                    "odp": p["odpowiedz"],
                }
                for p in etap_dane["pytania"]
            ],
            "pula": etap_dane.get("slowa_pula", []),
            "t": {
                "sprawdz": tt({"pl": "✔ Sprawdź", "en": "✔ Check"}),
                "podp": tt({"pl": "dotknij słowa, żeby wstawić je do zaznaczonego zdania",
                            "en": "tap a word to put it into the highlighted sentence"}),
                "zle": tt({"pl": "{n}/{m} dobrze — zdania na czerwono się nie zgadzają. Dotknij słowa, żeby je wyjąć.",
                           "en": "{n}/{m} correct — the red sentences are wrong. Tap a word to take it out."}),
                "dobrze": tt({"pl": "✨ Wszystko się zgadza!", "en": "✨ All correct!"}),
                "podpBtn": "💡 Podpowiedź",
                "podpBtnUzyta": "💡 Podpowiedź odkryta",
                "podpTytul": "Jedyna podpowiedź",
                "podpTekst": ("W <b>punkcie 3</b> skup się na słowie związanym ze <b>wstydem</b>. "
                              "Które z angielskich słów, które Ci zostały, mogłoby choć trochę pasować do wstydu? 😉"),
            },
        }
        html = SZABLON_KRZYZOWKI.replace("__DANE__", json.dumps(dane, ensure_ascii=False).replace("</", "<\\/"))
        wynik = gra_z_wynikiem(html, 900, key=f"kmp_{klucz}")
        return True if wynik else None

    # Zapas, gdy most do gier jest niedostepny - dotychczasowa wersja

    placeholder = t("wybierz")
    pula_wspolna = etap_dane.get("slowa_pula", [])
    odpowiedzi_uzytkownika = []
    for idx, pytanie in enumerate(etap_dane["pytania"]):
        st.markdown(f"**{idx + 1}.** {tt(pytanie['wskazowka'])}")
        if pytanie.get("podpowiedz"):
            st.caption(tt(pytanie["podpowiedz"]))
        typ_pytania = pytanie.get("typ", "tekst")

        if typ_pytania == "ulozanka":
            # Jedno pole na cale zdanie zamiast osobnej listy na kazde slowo
            # (bylo 13 list po 20 slow). Kolejnosc wyboru = kolejnosc w zdaniu.
            pula = pytanie.get("slowa_pula", pula_wspolna)
            liczba_slow = len(pytanie["odpowiedz"])
            wybrane_slowa = st.multiselect(
                tt({"pl": f"Wybierz {liczba_slow} słowa po kolei:", "en": f"Pick {liczba_slow} words in order:"}),
                pula,
                key=f"{klucz}_pyt_{idx}_zdanie",
                max_selections=liczba_slow,
                placeholder=tt({"pl": "dotknij, żeby wybrać słowo…", "en": "tap to pick a word…"}),
            )
            if wybrane_slowa:
                st.markdown(
                    "<div class='zdanie-podglad'>➜ " + " ".join(wybrane_slowa) + "</div>",
                    unsafe_allow_html=True,
                )
            odpowiedzi_uzytkownika.append(list(wybrane_slowa))
        else:
            wpisane = st.text_input(
                t("twoja_odpowiedz"), key=f"{klucz}_pyt_{idx}", label_visibility="collapsed"
            )
            odpowiedzi_uzytkownika.append(wpisane)

    if st.button(t("sprawdz"), key=f"btn_{klucz}"):
        wszystkie_poprawne = True
        for idx, pytanie in enumerate(etap_dane["pytania"]):
            typ_pytania = pytanie.get("typ", "tekst")
            if typ_pytania == "ulozanka":
                wybrane = [znormalizuj(w) for w in odpowiedzi_uzytkownika[idx]]
                oczekiwane = [znormalizuj(w) for w in pytanie["odpowiedz"]]
                if wybrane != oczekiwane:
                    wszystkie_poprawne = False
            else:
                wpisana = znormalizuj(odpowiedzi_uzytkownika[idx])
                akceptowane = [znormalizuj(a) for a in pytanie["odpowiedzi"]]
                if wpisana not in akceptowane:
                    wszystkie_poprawne = False
        if wszystkie_poprawne:
            return True
        st.error(t("zle_sprobuj"))
        return False
    return None


