def _klucz_postaci(tekst):
    import unicodedata
    t_ = unicodedata.normalize("NFD", str(tekst or "").lower())
    t_ = "".join(c for c in t_ if c.isalnum())
    return _ALIASY_LOL.get(t_, t_)


_ZNANE_POSTACIE = {_klucz_postaci(p): p for p in POSTACIE_LOL}


