def pokaz_powitanie():
    if "zamek_proby" not in st.session_state:
        st.session_state.zamek_proby = 0

    # Piate dotkniecie: animacja otwarcia, potem menu
    if st.session_state.get("zamek_otwieranie"):
        st.markdown("<div style='height:8vh;'></div>", unsafe_allow_html=True)
        components.html(ANIMACJA_KLODKI, height=420, scrolling=False)
        time.sleep(2.9)
        st.session_state.zamek_otwieranie = False
        st.session_state.ekran = "menu"
        st.session_state.czas_startu = time.time()
        rozpocznij_samouczek()
        zapisz_postep()
        st.rerun()
        return

    pokaz_baner_testowy()
    if tryb_testowy():
        if st.button(tt({"pl": "⏭️ Pomiń kłódki (wersja testowa)", "en": "⏭️ Skip the padlocks (test version)"}),
                     key="zalicz_test_klodki", use_container_width=True):
            st.session_state.ekran = "menu"
            st.session_state.czas_startu = time.time()
            rozpocznij_samouczek()
            zapisz_postep()
            st.rerun()

    proby = st.session_state.zamek_proby
    kropki = "".join(
        "<span style='width:10px;height:10px;border-radius:50%;display:inline-block;margin:0 4px;"
        + ("background:#ffd76a;box-shadow:0 0 9px rgba(255,215,106,0.85)" if k < proby
           else "background:rgba(230,193,92,0.22)") + "'></span>"
        for k in range(5)
    )
    napis = tt({"pl": "🔍 Znajdź i otwórz 5 kłódek", "en": "🔍 Find and open 5 padlocks"})
    st.markdown(
        f"<div style='text-align:center;margin-top:0.4rem;color:#ffe08a;font-weight:800;font-size:1.05rem;"
        f"letter-spacing:0.02em;text-shadow:0 0 12px rgba(255,210,110,0.35);'>{napis}</div>"
        f"<div style='text-align:center;margin-top:0.45rem;'>{kropki}</div>",
        unsafe_allow_html=True,
    )

    # Klodka jest przypieta do ekranu (position:fixed) w losowym, ale zawsze
    # WIDOCZNYM miejscu - dawniej odstep o losowej wysokosci rozciagal strone
    # i trzeba bylo ja przewijac. Przewijanie tego ekranu blokuje CSS (:has).
    losowe_x = random.choice([18, 26, 34, 42, 50, 58, 66, 74, 82])      # srodek klodki, % szerokosci
    losowe_y = random.choice([46, 52, 58, 64, 70, 76])                  # srodek klodki, % wysokosci
    gora_min = 400 if tryb_testowy() else 210                          # pod naglowkiem (i banerem testowym)
    kliknieto = st.button("🔒", key="zamek_btn")

    # WAZNE: st.markdown/st.html z <style> okazal sie zawodny przy KOLEJNYCH
    # przebiegach skryptu - to udokumentowany problem samego Streamlita
    # (CSS ladowany jest do strony, ale przegladarka nie stosuje go ponownie
    # po zmianie, mimo ze recznie wklejony ten sam kod dziala). Dlatego
    # zamiast liczyc na arkusz stylow, ustawiamy wyglad i pozycje
    # BEZPOSREDNIO przez JS (element.style.wlasciwosc = wartosc) z wnetrza
    # malego komponentu - components.html tworzy swieza ramke za kazdym
    # razem, wiec nie ma tu czego "nie odswiezyc".
    components.html(
        f"""
        <script>
          (function () {{
            try {{
              var doc = window.parent.document;
              var wrapper = doc.querySelector('.st-key-zamek_btn');
              if (!wrapper) return;
              wrapper.style.width = 'fit-content';
              wrapper.style.marginLeft = '0';
              wrapper.style.position = 'fixed';
              wrapper.style.zIndex = '50';
              wrapper.style.left = 'clamp(8px, calc({losowe_x}vw - 80px), calc(100vw - 168px))';
              wrapper.style.top = 'clamp({gora_min}px, calc({losowe_y}vh - 80px), calc(100vh - 176px))';
              wrapper.style.top = 'clamp({gora_min}px, calc({losowe_y}dvh - 80px), calc(100dvh - 176px))';
              var btn = wrapper.querySelector('button');
              if (!btn) return;
              // Samo emoji - bez tla/ramki/cienia, tylko wieksze i z
              // delikatna, pulsujaca poswiata WOKOL SAMEGO ZNAKU
              // (filter:drop-shadow dziala na przezroczystym tle).
              btn.style.width = '160px';
              btn.style.height = '160px';
              btn.style.minHeight = '160px';
              btn.style.borderRadius = '0';
              btn.style.fontSize = '6rem';
              btn.style.padding = '0';
              btn.style.display = 'flex';
              btn.style.alignItems = 'center';
              btn.style.justifyContent = 'center';
              btn.style.background = 'transparent';
              btn.style.boxShadow = 'none';
              btn.style.border = 'none';

              // Drgniecie po kazdym dotknieciu (kropki postepu sa na gorze ekranu,
              // nie pod klodka - pod nia zdradzaly, gdzie jej szukac)
              var proby = {st.session_state.zamek_proby};
              var staryPostep = wrapper.querySelector('#postepZamka');
              if (staryPostep) staryPostep.remove();
              btn.style.visibility = 'visible';   // stara kopia byla chowana w chwili dotkniecia
              if (proby > 0 && btn.animate) {{
                btn.animate([{{transform:'scale(0.3)', opacity:0}}, {{transform:'scale(1.12)', opacity:1, offset:0.7}},
                             {{transform:'scale(1)', opacity:1}}],
                            {{duration: 520, easing: 'ease-out'}});
              }}
              // Funkcja tworzona w oknie STRONY - przezyje zniszczenie tej ramki
              if (!btn.dataset.dzwiek) {{
                btn.dataset.dzwiek = '1';
                btn.addEventListener('pointerdown', new window.parent.Function('ev', {json.dumps(KOD_KLIKNIECIA_ZAMKA)}));
              }}

              var styl = doc.getElementById('styl-pulsowania-zamka');
              if (!styl) {{
                styl = doc.createElement('style');
                styl.id = 'styl-pulsowania-zamka';
                styl.textContent =
                  '@keyframes pulsujZamekPowitanie {{' +
                  '0%,100% {{ filter: drop-shadow(0 0 0px rgba(230,193,92,0)); }}' +
                  '50% {{ filter: drop-shadow(0 0 22px rgba(230,193,92,0.9)); }}' +
                  '}}';
                doc.head.appendChild(styl);
              }}
              btn.style.animation = 'pulsujZamekPowitanie 2.4s ease-in-out infinite';
            }} catch (e) {{}}
          }})();
        </script>
        """,
        height=1,
    )

    if kliknieto:
        st.session_state.zamek_proby += 1
        if st.session_state.zamek_proby >= 5:
            st.session_state.zamek_otwieranie = True
        st.rerun()


def _postep_kategorii(kat):
    etapy = etapy_kategorii(kat)
    zrobione = sum(1 for e in etapy if e["klucz"] in st.session_state.rozwiazane)
    return zrobione, len(etapy)


def pokaz_menu():
    st.session_state.pop("gra_dalej_klucz", None)
    pokaz_baner_testowy()
    st.markdown(f"<h1 class='tytul'>{t('menu_tytul')}</h1>", unsafe_allow_html=True)

    zrobione_lacznie = sum(1 for e in ETAPY if e["klucz"] in st.session_state.rozwiazane)
    proc_globalny = int(zrobione_lacznie / len(ETAPY) * 100) if ETAPY else 0
    # Jeden zamkniety blok HTML. Rozbijanie go na kilka wywolan markdown
    # NIE dziala - Streamlit renderuje kazde jako osobny fragment DOM,
    # wiec niedomkniety <div> nie opakowuje tego, co po nim nastepuje.
    st.markdown(
        f"""
        <div class='pasek-globalny'>
          <div class='pasek-globalny-wyp' style='width:{proc_globalny}%'></div>
        </div>
        """,
        unsafe_allow_html=True,
    )

    pokaz_przycisk_wiadomosci()

    # Kategorie: caly kafelek to przycisk. Pasek postepu rysujemy znakami,
    # bo do etykiety przycisku nie da sie wstrzyknac wlasnego HTML.
    # Oglaszamy tylko levele odblokowane W TEJ sesji - nie przy kazdym odswiezeniu
    otwarte = {i for i, k in enumerate(KATEGORIE) if not _zablokowany_bez_testu(k)}
    if "levele_na_starcie" not in st.session_state:
        st.session_state.levele_na_starcie = set(otwarte)
    ogloszone = st.session_state.setdefault("levele_ogloszone", set())
    for nowy in sorted(otwarte - st.session_state.levele_na_starcie - ogloszone):
        ogloszone.add(nowy)
        st.success(t("level_odblokowany").format(n=nowy + 1))
        st.balloons()

    for kat in KATEGORIE:
        if _dostep_zablokowany(kat):
            # Licznik pokazuje WLASNE gry levelu - wczesniej byl tu postep
            # wszystkich poprzednich leveli razem (np. "x/20" przy Level 3)
            zrobione_z, ile_z = _postep_kategorii(kat)
            st.button(
                f"🔒\n\n**{tt(kat['nazwa'])}**\n\n{tt(kat['opis'])}\n\n"
                f"{t('level_zablokowany').format(n=KATEGORIE.index(kat))}\n\n"
                f"{'▰' * zrobione_z}{'▱' * (ile_z - zrobione_z)}  {zrobione_z}/{ile_z}",
                key=f"kat_{kat['id']}", use_container_width=True,
                type="primary", disabled=True,
            )
            if tryb_testowy():
                if st.button("🧪 Otwórz mimo blokady (wersja testowa)",
                             key=f"zalicz_test_otworz_{kat['id']}", use_container_width=True):
                    st.session_state.test_obejscie = True
                    st.session_state.ekran = f"kategoria:{kat['id']}"
                    st.rerun()
            continue
        zrobione, ile = _postep_kategorii(kat)
        pasek = "▰" * zrobione + "▱" * (ile - zrobione)   # jedna kratka = jedna gra
        znacznik = " ✅" if zrobione == ile else ""
        etykieta = (
            f"**{tt(kat['nazwa'])}**{znacznik}\n\n"
            f"{tt(kat['opis'])}\n\n"
            f"{pasek}  {zrobione}/{ile}"
        )
        if st.button(
            etykieta,
            key=f"kat_{kat['id']}",
            use_container_width=True,
            type="primary",
        ):
            st.session_state.ekran = f"kategoria:{kat['id']}"
            st.rerun()

    wszystkie = all(e["klucz"] in st.session_state.rozwiazane for e in ETAPY)
    if wszystkie:
        st.success(t("wszystko_rozwiazane"))
        if st.button(t("zobacz_kod"), key="zobacz_kod_btn", use_container_width=True):
            st.session_state.ekran = "final"
            st.rerun()

    st.markdown("<div style='margin-top:2rem;'></div>", unsafe_allow_html=True)
    pokaz_przycisk_resetu()

# ---------------------------------------------------------------------------
# TEST NA NIE-BYCIE-ROBOTEM
# Druga szansa dla etapu jednej proby. Cztery kroki, kazdy z haczykiem.
# Bledna odpowiedz nie cofa postepu testu - to ma byc zabawa, nie kara.
# ---------------------------------------------------------------------------
KAPCZA_POLA = ["🚦", "🌳", "🚥", "🚗", "🟢", "🚦", "🍎", "🚲", "🚥"]
KAPCZA_POPRAWNE = {0, 2, 5, 8}
KAPCZA_TEKST = "JESTEM CZŁOWIEKIEM"


def _normalizuj(tekst):
    zamiana = str.maketrans("ąćęłńóśźż", "acelnoszz")
    return "".join(tekst.lower().translate(zamiana).split())


def _tekst_znieksztalcony(tekst):
    # Kazda litera krzywo, w innym kroju i kolorze - jak prawdziwa kapcza
    kroje = ["Georgia", "Courier New", "Impact", "Trebuchet MS", "Times New Roman"]
    kolory = ["#e6c15c", "#b48ce6", "#7ec98a", "#e87c7c", "#7ea8e6"]
    litery = []
    for i, z in enumerate(tekst):
        if z == " ":
            litery.append("<span style='display:inline-block;width:0.5em'></span>")
            continue
        obrot = ((i * 37) % 50) - 25
        dy = ((i * 53) % 14) - 7
        rozmiar = 1.5 + ((i * 17) % 7) / 10
        litery.append(
            f"<span style='display:inline-block;transform:rotate({obrot}deg) translateY({dy}px);"
            f"font-family:{kroje[i % len(kroje)]};color:{kolory[(i * 3) % len(kolory)]};"
            f"font-size:{rozmiar}rem;font-weight:700;margin:0 1px'>{z}</span>"
        )
    return (
        "<div style='position:relative;text-align:center;padding:18px 6px;margin:8px 0 12px;"
        "background:repeating-linear-gradient(35deg,#1c1828 0 7px,#221d30 7px 14px);"
        "border-radius:12px;overflow:hidden'>"
        + "".join(litery)
        + "<div style='position:absolute;left:4%;right:4%;top:52%;height:2px;"
        "background:#e6c15c;opacity:0.6;transform:rotate(-3deg)'></div></div>"
    )


def pokaz_test_robota(klucz):
    """Zwraca True, gdy wszystkie cztery kroki zostaly zaliczone."""
    stan = st.session_state.setdefault("kapcza", {})
    krok = stan.get(klucz, 1)

    st.error(tt({
        "pl": "🔒 Zła odpowiedź — jedyna szansa wykorzystana.",
        "en": "🔒 Wrong answer — your only shot is used.",
    }))
    st.markdown(tt({
        "pl": "Ale jest jeszcze jedno wyjście. Musisz tylko udowodnić, że **nie jesteś robotem**. 🤖",
        "en": "But there's one way out. You just have to prove you're **not a robot**. 🤖",
    }))
    st.caption(f"{tt({'pl': 'Krok', 'en': 'Step'})} {min(krok, 4)} / 4")

    if krok == 1:
        st.markdown(tt({
            "pl": "**Zaznacz wszystkie pola z sygnalizacją świetlną.**",
            "en": "**Select all squares with traffic lights.**",
        }))
        kolumny = st.columns(3)
        zaznaczone = set()
        for i, emoji in enumerate(KAPCZA_POLA):
            with kolumny[i % 3]:
                if st.checkbox(emoji, key=f"kapcza1_{klucz}_{i}"):
                    zaznaczone.add(i)
        if st.button(tt({"pl": "Sprawdź", "en": "Check"}), key=f"kapcza_spr1_{klucz}"):
            if zaznaczone == KAPCZA_POPRAWNE:
                stan[klucz] = 2
                st.rerun()
            elif 4 in zaznaczone:
                st.warning(tt({
                    "pl": "🟢 To jest zielone kółko. Dokładnie tak pomyliłby się robot. 🤨",
                    "en": "🟢 That's a green circle. Exactly the mistake a robot would make. 🤨",
                }))
            else:
                st.warning(tt({
                    "pl": "Hmm. Tak zaznaczyłby robot. Przyjrzyj się jeszcze raz.",
                    "en": "Hmm. That's how a robot would answer. Look again.",
                }))

    elif krok == 2:
        st.markdown(tt({
            "pl": "**Przepisz tekst z obrazka.**",
            "en": "**Type the text from the image.**",
        }))
        st.markdown(_tekst_znieksztalcony(KAPCZA_TEKST), unsafe_allow_html=True)
        odp = st.text_input(tt({"pl": "Tekst", "en": "Text"}), key=f"kapcza2_{klucz}")
        if st.button(tt({"pl": "Sprawdź", "en": "Check"}), key=f"kapcza_spr2_{klucz}"):
            if _normalizuj(odp) == _normalizuj(KAPCZA_TEKST):
                stan[klucz] = 3
                st.rerun()
            else:
                st.warning(tt({
                    "pl": "Nie zgadza się. Roboty też mają z tym problem, więc to wciąż nic nie przesądza.",
                    "en": "Doesn't match. Robots struggle with this too, so that proves nothing yet.",
                }))

    elif krok == 3:
        st.markdown(tt({
            "pl": "**Kot ma tyle nóg, ile ma. Pomnóż to przez liczbę dni w lutym roku "
                  "przestępnego i odejmij 100.**",
            "en": "**A cat has as many legs as it has. Multiply that by the number of days "
                  "in February of a leap year and subtract 100.**",
        }))
        odp = st.text_input(tt({"pl": "Wynik", "en": "Result"}), key=f"kapcza3_{klucz}")
        if st.button(tt({"pl": "Sprawdź", "en": "Check"}), key=f"kapcza_spr3_{klucz}"):
            if odp.strip() == "16":
                stan[klucz] = 4
                st.rerun()
            else:
                st.warning(tt({
                    "pl": "🐈 Kot patrzy na Ciebie z politowaniem. Policz jeszcze raz.",
                    "en": "🐈 The cat looks at you with pity. Try again.",
                }))

    else:
        st.markdown(tt({"pl": "**Ostatnie pytanie. Czy jesteś robotem?**",
                        "en": "**Last question. Are you a robot?**"}))
        opcje = ["Tak", "Nie", "01001110 01101001 01100101", "Beep boop 🤖"]
        odp = st.radio(" ", opcje, key=f"kapcza4_{klucz}", label_visibility="collapsed")
        if st.button(tt({"pl": "Potwierdzam", "en": "Confirm"}), key=f"kapcza_spr4_{klucz}"):
            if odp == "Nie":
                return True
            komunikaty = {
                "Tak": {"pl": "Szczerość doceniamy. Wstęp wzbroniony. 🚫",
                        "en": "We appreciate the honesty. Access denied. 🚫"},
                "01001110 01101001 01100101": {
                    "pl": "To znaczy „Nie”… ale zapisane binarnie. Bardzo podejrzane. 🤨",
                    "en": "That means “Nie” (No)… but in binary. Very suspicious. 🤨"},
                "Beep boop 🤖": {"pl": "No i się wydało.", "en": "Well, that gives it away."},
            }
            st.warning(tt(komunikaty[odp]))
    return False


def _rozpocznij_powtorke(klucz):
    st.session_state.setdefault("tryb_powtorki", set()).add(klucz)
    nr = st.session_state.setdefault("nr_powtorki", {})
    nr[klucz] = nr.get(klucz, 0) + 1


def pokaz_ekran_etapu(etap_dane):
    klucz = etap_dane["klucz"]
    st.session_state.etap_biezacy = klucz

    if st.button(t("wroc_do_menu"), key=f"powrot_{klucz}"):
        # Wyjscie z etapu konczy tryb powtorki - po powrocie widac status
        st.session_state.setdefault("tryb_powtorki", set()).discard(klucz)
        st.session_state.pop("gra_dalej_klucz", None)   # koniec gry "po progu"
        st.session_state.ekran = "menu"
        st.rerun()

    if tryb_testowy() and klucz not in st.session_state.rozwiazane:
        if st.button(tt({"pl": "⏭️ Pomiń ten etap (wersja testowa)", "en": "⏭️ Skip this stage (test version)"}),
                     key=f"zalicz_test_{klucz}", use_container_width=True):
            st.session_state.nieudane.discard(klucz)
            st.session_state.rozwiazane.add(klucz)
            zapisz_postep()
            st.rerun()

    if _dostep_zablokowany(_kategoria_etapu(klucz)) and klucz not in st.session_state.rozwiazane:
        kat_e = _kategoria_etapu(klucz)
        st.info(t("level_zablokowany").format(n=KATEGORIE.index(kat_e)))
        return

    st.markdown(f"<h2 class='tytul' style='font-size:1.5rem;'>{tt(etap_dane['tytul'])}</h2>", unsafe_allow_html=True)
    # Instrukcja etapu (krzyzowka, rebus) - byla w danych, ale nigdzie sie nie wyswietlala
    if etap_dane.get("info"):
        st.markdown(f"<div class='info-etapu'>💡 {tt(etap_dane['info'])}</div>", unsafe_allow_html=True)

    powtorka = klucz in st.session_state.get("tryb_powtorki", set())
    # Gra, ktora po progu toczy sie dalej, zostaje na ekranie zamiast "Rozwiazane"
    kontynuuje = st.session_state.get("gra_dalej_klucz") == klucz
    if klucz in st.session_state.rozwiazane and not powtorka and not kontynuuje:
        st.success(t("rozwiazane_status"))
        pokaz_karte_statystyk(klucz)
        st.caption(t("powtorka_info"))
        if st.button(t("zagraj_ponownie"), key=f"powtorz_{klucz}", use_container_width=True):
            _rozpocznij_powtorke(klucz)
            st.rerun()
        if st.button(t("wroc_do_menu"), key=f"menu_po_{klucz}", use_container_width=True):
            _wroc_do_menu(klucz)
        return
    if powtorka:
        st.info(t("tryb_powtorki_info"))
    if klucz in st.session_state.nieudane and not powtorka:
        if pokaz_test_robota(klucz):
            st.session_state.nieudane.discard(klucz)
            st.session_state.rozwiazane.add(klucz)
            zapisz_postep()
            st.balloons()
            st.rerun()
        return

    typ = etap_dane["typ"]
    if typ == "haslo":
        wynik = renderuj_haslo(etap_dane)
    elif typ == "krzyzowka":
        wynik = renderuj_krzyzowka(etap_dane)
    elif typ == "rebus":
        wynik = renderuj_rebus(etap_dane)
    elif typ == "quiz":
        wynik = renderuj_quiz(etap_dane)
    elif typ == "gra":
        wynik = renderuj_gra(etap_dane)
    elif typ == "dron":
        wynik = renderuj_dron(etap_dane)
    elif typ == "bungee":
        wynik = renderuj_bungee(etap_dane)
    elif typ == "zaba":
        wynik = renderuj_zaba(etap_dane)
    elif typ == "memory":
        wynik = renderuj_memory(etap_dane)
    elif typ == "simon":
        wynik = renderuj_simon(etap_dane)
    elif typ == "piano":
        wynik = renderuj_piano(etap_dane)
    elif typ == "wordle":
        wynik = renderuj_wordle(etap_dane)
    elif typ == "data":
        wynik = renderuj_data(etap_dane)
    elif typ == "szachy":
        wynik = renderuj_szachy(etap_dane)
    elif typ == "bitwa":
        wynik = renderuj_bitwa(etap_dane)
    elif typ == "minecraft":
        wynik = renderuj_minecraft(etap_dane)
    elif typ == "snake":
        wynik = renderuj_snake(etap_dane)
    elif typ == "blackjack":
        wynik = renderuj_blackjack(etap_dane)
    elif typ == "samolot":
        wynik = renderuj_samolot(etap_dane)
    elif typ == "odyseusz":
        wynik = renderuj_odyseusz(etap_dane)
    elif typ == "parkour":
        wynik = renderuj_parkour(etap_dane)
    elif typ == "labirynt":
        wynik = renderuj_labirynt(etap_dane)
    elif typ == "poziom_diabla":
        wynik = renderuj_poziom_diabla(etap_dane)
    else:
        wynik = None

    if powtorka:
        # Powtorka: zadnych zmian w postepie. Pomylka nie zamyka etapu
        # jednej proby, a wygrana nie dolicza nic do wiadomosci.
        if wynik is True:
            st.success(t("powtorka_ukonczona"))
            st.balloons()
            if st.button(t("zagraj_ponownie"), key=f"powtorz_znow_{klucz}", use_container_width=True):
                _rozpocznij_powtorke(klucz)
                st.rerun()
            if st.button(t("wroc_do_menu"), key=f"menu_po_powtorce_{klucz}", use_container_width=True):
                _wroc_do_menu(klucz)
        return

    if wynik is True:
        nowe = klucz not in st.session_state.rozwiazane
        st.session_state.rozwiazane.add(klucz)
        zapisz_postep()
        if nowe:
            st.balloons()
        if st.session_state.pop("graj_dalej", False):
            st.success(tt({"pl": "✅ Gra zaliczona! Możesz grać dalej albo wrócić do menu.",
                           "en": "✅ Game completed! Keep playing or go back to the menu."}))
            if st.button(t("wroc_do_menu"), key=f"menu_dalej_{klucz}", use_container_width=True):
                _wroc_do_menu(klucz)
            return
        st.rerun()
    elif wynik is False:
        st.session_state.bledy_per_etap[klucz] = st.session_state.bledy_per_etap.get(klucz, 0) + 1
        if etap_dane.get("jedna_proba"):
            st.session_state.nieudane.add(klucz)
        zapisz_postep()


