def pokaz_kategorie(kat):
    st.markdown(
        f"<h1 class='tytul' style='color:{kat['kolor']}'>{kat['emoji']} {tt(kat['nazwa'])}</h1>",
        unsafe_allow_html=True,
    )
    zrobione, ile = _postep_kategorii(kat)
    st.markdown(
        f"<p class='licznik-globalny'>{zrobione} / {ile} {t('ukonczonych')}</p>",
        unsafe_allow_html=True,
    )

    etapy = etapy_kategorii(kat)
    # Lista BEZ kolumn. W kolumnach przycisk lapie regula gry z klodka na
    # ekranie powitalnym (kwadrat, przezroczyste tlo, olbrzymia czcionka),
    # a na telefonie kolumny i tak ukladaja sie jedna pod druga.
    # Przedrostek klucza niesie stan etapu, zeby CSS mogl go pokolorowac.
    for etap_dane in etapy:
        klucz = etap_dane["klucz"]
        rozwiazany = klucz in st.session_state.rozwiazane
        nieudany = klucz in st.session_state.nieudane
        nazwa = tt(etap_dane["tytul"])
        if rozwiazany:
            etykieta, przedrostek = nazwa + "  ✅", "menu_ok_"
        elif nieudany:
            etykieta, przedrostek = nazwa + "  🤖", "menu_rb_"
        else:
            etykieta, przedrostek = nazwa, "menu_"
        if st.button(etykieta, key=przedrostek + klucz, use_container_width=True):
            st.session_state.ekran = f"etap:{klucz}"
            st.rerun()

    st.markdown("<div style='margin-top:1.4rem;'></div>", unsafe_allow_html=True)
    if st.button(t("powrot_kategorie"), key="powrot_do_kategorii"):
        st.session_state.ekran = "menu"
        st.rerun()


# ---------- PAMIEC POSTEPU W TELEFONIE ----------
# Ponowne zeskanowanie QR otwiera adres BEZ parametrow, wiec aplikacja
# losowalaby nowy identyfikator i zaczynala od zera. Pliki na Streamlit
# Cloud tez nie sa trwale (znikaja przy wybudzeniu z uspienia). Dlatego
# kopia adresu z postepem lezy w localStorage telefonu i jest przywracana.
PRZYWRACANIE_Z_PRZEGLADARKI = True

SKRYPT_PAMIECI = """<script>
(function () {
  var K = 'escape_room_postep_v1';
  var SWIEZY = __SWIEZY__, ZAPIS = __ZAPIS__, WYCZYSC = __WYCZYSC__;
  var okno = window.parent || window, pam = null, ses = null;
  try { pam = okno.localStorage; } catch (e) { try { pam = window.localStorage; } catch (e2) {} }
  try { ses = okno.sessionStorage; } catch (e) {}
  if (!pam) return;
  // Po resecie: liczniki gier i "labirynt przeszly" z testow nie moga
  // trafic do prawdziwej rozgrywki
  if (WYCZYSC) {
    try {
      var doUsuniecia = [];
      for (var i = 0; i < pam.length; i++) {
        var kl = pam.key(i);
        if (kl && (kl.indexOf('staty_gry_') === 0 || kl === 'labiryntPrzeszly')) doUsuniecia.push(kl);
      }
      doUsuniecia.forEach(function (kl) { pam.removeItem(kl); });
    } catch (e) {}
  }
  try {
    if (SWIEZY) {
      var stary = pam.getItem(K);
      var juz = ses ? ses.getItem(K + '_raz') : null;
      // Najwyzej jedno przekierowanie na karte - zadnej szansy na petle
      if (stary && stary.indexOf('u=') >= 0 && !juz) {
        if (ses) ses.setItem(K + '_raz', '1');
        var biezace = new URLSearchParams(okno.location.search), tst = biezace.get('test');
        okno.location.replace(okno.location.pathname + '?' + stary + (tst ? '&test=' + encodeURIComponent(tst) : ''));
      }
    } else if (ZAPIS && ZAPIS.indexOf('u=') >= 0) {
      pam.setItem(K, ZAPIS);
    }
  } catch (e) {}
})();
</script>"""


def pamiec_przegladarki(swiezy):
    if not PRZYWRACANIE_Z_PRZEGLADARKI:
        return
    from urllib.parse import urlencode
    parametry = {k: st.query_params.get(k) for k in list(st.query_params) if k not in ("resetuj", "test", "samouczek")}
    wyczysc = bool(st.session_state.get("po_resecie")) and not st.session_state.get("wyczyszczono_lokalne")
    if wyczysc:
        st.session_state.wyczyszczono_lokalne = True
    zapis = urlencode(parametry)
    components.html(
        SKRYPT_PAMIECI.replace("__SWIEZY__", "true" if swiezy else "false")
                      .replace("__ZAPIS__", json.dumps(zapis))
                      .replace("__WYCZYSC__", "true" if wyczysc else "false"),
        height=0,
    )


def main():
    st.set_page_config(page_title=f"Dla {IMIE}", page_icon="🔒", layout="centered")
    wstaw_styl()

    if st.query_params.get("resetuj") == "tak":
        sciezka = sciezka_stanu()
        if os.path.exists(sciezka):
            os.remove(sciezka)
        st.session_state.clear()
        # Po resecie NIE przywracamy starego postepu z pamieci telefonu -
        # nastepny przebieg nadpisze ja czystym stanem.
        st.session_state["po_resecie"] = True
        try:
            st.query_params.clear()
        except Exception:
            pass
        st.rerun()

    # Decyzje podejmujemy PRZED zainicjuj_stan(), bo ten od razu losuje nowe
    # ?u= - skrypt w przegladarce widzialby juz nowy adres i nic nie przywrocil.
    swiezy = ("u" not in st.query_params) and not st.session_state.get("po_resecie")

    _odczytaj_tryb_testowy()
    zainicjuj_stan()
    _odczytaj_samouczek_param()

    ekran = st.session_state.ekran
    krok_samouczka = _samouczek_krok()

    if krok_samouczka and ekran == "menu":
        pokaz_samouczek(krok_samouczka)
    elif ekran == "powitanie":
        pokaz_powitanie()
    elif ekran == "final":
        pokaz_final()
    elif ekran == "wiadomosc":
        pokaz_ukryta_wiadomosc()
        pokaz_przycisk_kodu_pod_wiadomoscia()
    elif ekran.startswith("kategoria:"):
        kat_id = ekran.split(":", 1)[1]
        kat = next((k for k in KATEGORIE if k["id"] == kat_id), None)
        if kat is None or _dostep_zablokowany(kat):
            st.session_state.ekran = "menu"
            st.rerun()
        else:
            pokaz_kategorie(kat)
    elif ekran.startswith("etap:"):
        klucz = ekran.split(":", 1)[1]
        etap_dane = next((e for e in ETAPY if e["klucz"] == klucz), None)
        if etap_dane is None:
            st.session_state.ekran = "menu"
            st.rerun()
        else:
            pokaz_ekran_etapu(etap_dane)
    else:
        pokaz_menu()

    pamiec_przegladarki(swiezy)


if __name__ == "__main__":
    main()
